Cypress.Commands.add('login', (email: string, password: string) => {
  cy.session([email, password], () => {
    cy.visit('/login')
    cy.get('[name=email]').type(email)
    cy.get('[name=password]').type(password)
    cy.get('form').submit()
    cy.url().should('include', '/dashboard')
  })
})

// cypress.d.ts
export {}
declare global {
  namespace Cypress {
    interface Chainable {
      login(email: string, password: string): Chainable<void>
    }
  }
}

describe('dashboard', () => {
  beforeEach(() => {
    cy.session('alice', () => {
      cy.visit('/login')
      cy.get('[name=email]').type('[email protected]')
      cy.get('[name=password]').type('secret')
      cy.get('button[type=submit]').click()
      cy.url().should('include', '/dashboard')
    })

    cy.visit('/dashboard')
  })

  it('shows the dashboard', () => {
    cy.contains('Dashboard').should('be.visible')
  })
})

describe('users', () => {
  beforeEach(() => {
    cy.intercept('GET', '/api/users', { fixture: 'users.json' }).as('getUsers')
  })

  it('shows fixture-backed users', () => {
    cy.visit('/users')
    cy.wait('@getUsers')
    cy.get('[data-cy="user"]').should('have.length', 2)
  })
})

describe('login', () => {
  it('shows the dashboard', () => {
    cy.visit('/login')
    cy.get('[data-cy=email]').type('user@example.com')
    cy.get('[data-cy=password]').type('secret')
    cy.get('[data-cy=submit]').click()
    cy.url().should('include', '/dashboard')
  })
})

describe('checkout', { retries: { runMode: 2, openMode: 0 } }, () => {
  it('shows the confirmation', () => {
    cy.visit('/checkout')
    cy.get('[data-cy=submit]').click()
    cy.get('[data-cy=confirmation]').should('be.visible')
  })
})

